-- Quest 26706: native hippogryph boarding and scoped Russian dialogue.
SET NAMES utf8mb4;
INSERT INTO npc_spellclick_spells(npc_entry,spell_id,cast_flags,user_type) SELECT 43751,46598,1,0 WHERE EXISTS(SELECT 1 FROM creature_template WHERE entry=43751 AND VehicleId=641 AND ScriptName='npc_hippogryph_43751' AND AIName='') AND NOT EXISTS(SELECT 1 FROM npc_spellclick_spells WHERE npc_entry=43751);
-- Do not permanently enable spellclick: Tobias controls the departure window.
INSERT INTO creature_text_locale(CreatureID,GroupID,ID,Locale,Text) SELECT 43566,0,0,'ruRU','В атаку!' WHERE EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=0 AND ID=0 AND Text='Attack!') AND NOT EXISTS(SELECT 1 FROM creature_text_locale WHERE CreatureID=43566 AND GroupID=0 AND ID=0);
UPDATE creature_text_locale SET Text='В атаку!' WHERE CreatureID=43566 AND GroupID=0 AND ID=0 AND Locale='ruRU' AND (Text IS NULL OR Text IN ('','Attack!')) AND EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=0 AND ID=0 AND Text='Attack!');
INSERT INTO creature_text_locale(CreatureID,GroupID,ID,Locale,Text) SELECT 43566,1,0,'ruRU','Зачистите верхнюю палубу!' WHERE EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=1 AND ID=0 AND Text='Secure the rafters!') AND NOT EXISTS(SELECT 1 FROM creature_text_locale WHERE CreatureID=43566 AND GroupID=1 AND ID=0);
