INSERT INTO creature_text_locale(CreatureID,GroupID,ID,Locale,Text) SELECT 43566,2,0,'ruRU','Два стрелка останутся здесь и прикроют палубу. Остальные, спускайтесь по верёвкам. Зададим им жару!' WHERE EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=2 AND ID=0 AND Text='I want two sharpshooters to stay behind and cover the deck.  Everyone else, use the ropes to rappel down.  Let''s give them hell!') AND NOT EXISTS(SELECT 1 FROM creature_text_locale WHERE CreatureID=43566 AND GroupID=2 AND ID=0);
UPDATE creature_text_locale SET Text='Два стрелка останутся здесь и прикроют палубу. Остальные, спускайтесь по верёвкам. Зададим им жару!' WHERE CreatureID=43566 AND GroupID=2 AND ID=0 AND Locale='ruRU' AND (Text IS NULL OR Text IN ('','I want two sharpshooters to stay behind and cover the deck.  Everyone else, use the ropes to rappel down.  Let''s give them hell!')) AND EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=2 AND ID=0 AND Text='I want two sharpshooters to stay behind and cover the deck.  Everyone else, use the ropes to rappel down.  Let''s give them hell!');
INSERT INTO creature_text_locale(CreatureID,GroupID,ID,Locale,Text) SELECT 43566,3,0,'ruRU','Руки вверх, зеленокожие! Мои люди зададут вам новый курс. Попробуете выкинуть что-нибудь — получите пулю.' WHERE EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=3 AND ID=0 AND Text='Hands up, greenskins!  My men will give you your new bearing.  You try anything funny and we''ll fill you with lead.') AND NOT EXISTS(SELECT 1 FROM creature_text_locale WHERE CreatureID=43566 AND GroupID=3 AND ID=0);
UPDATE creature_text_locale SET Text='Руки вверх, зеленокожие! Мои люди зададут вам новый курс. Попробуете выкинуть что-нибудь — получите пулю.' WHERE CreatureID=43566 AND GroupID=3 AND ID=0 AND Locale='ruRU' AND (Text IS NULL OR Text IN ('','Hands up, greenskins!  My men will give you your new bearing.  You try anything funny and we''ll fill you with lead.')) AND EXISTS(SELECT 1 FROM creature_text WHERE CreatureID=43566 AND GroupID=3 AND ID=0 AND Text='Hands up, greenskins!  My men will give you your new bearing.  You try anything funny and we''ll fill you with lead.');
