INSERT INTO quest_template_locale(ID,locale,LogTitle,LogDescription,QuestDescription) SELECT 26706,'ruRU','Эндшпиль','По сигналу Тобиаса оседлайте гиппогрифа и уничтожьте боевой корабль Орды.','Если мы хотим дать нашим людям шанс на спасение, надо уничтожить этот боевой корабль Орды.$B$BПлан такой: среди обитателей Килевой гавани всегда было немало сочувствующих мятежникам. Я уже нашла порядочное количество взрывчатки на одном складе.$B$BЭтого хватит, чтобы незаметно напасть на врага малым отрядом. Тут-то нам и пригодятся гиппогрифы ночных эльфов...$B$BТобиас подаст тебе сигнал, когда мы будем готовы.' WHERE EXISTS(SELECT 1 FROM quest_template WHERE ID=26706) AND NOT EXISTS(SELECT 1 FROM quest_template_locale WHERE ID=26706 AND locale='ruRU');
INSERT INTO quest_offer_reward_locale(ID,locale,RewardText)
SELECT 26706,'ruRU','Мы справились, $n! Эвакуация началась. Если мы отплывём сейчас, флот Отрекшихся останется далеко позади.'
WHERE EXISTS(SELECT 1 FROM quest_offer_reward WHERE ID=26706)
 AND NOT EXISTS(SELECT 1 FROM quest_offer_reward_locale WHERE ID=26706 AND locale='ruRU');
INSERT INTO quest_request_items_locale(ID,locale,CompletionText)
SELECT 26706,'ruRU','Стоит рисковать лишь ради побед, которые того заслуживают.'
WHERE EXISTS(SELECT 1 FROM quest_request_items WHERE ID=26706)
 AND NOT EXISTS(SELECT 1 FROM quest_request_items_locale WHERE ID=26706 AND locale='ruRU');
